/* General Styles */
body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    background-color: #f5f5f5;
    color: #333;
}

header {
    background-color: #4CAF50;
    color: white;
    padding: 15px 20px;
    text-align: center;
    font-size: 24px;
}

nav {
    background-color: #333;
    overflow: hidden;
}

nav a {
    float: left;
    display: block;
    color: white;
    text-align: center;
    padding: 14px 16px;
    text-decoration: none;
}

nav a:hover {
    background-color: #ddd;
    color: black;
}

.container {
    width: 90%;
    margin: auto;
    padding: 20px;
}

/* Problem Library */
.problem-library {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: 20px;
}

.problem-item {
    background: white;
    border: 1px solid #ddd;
    border-radius: 5px;
    padding: 15px;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

.problem-item h3 {
    margin-top: 0;
}

.problem-item p {
    color: #666;
}

/* Code Editor */
.code-editor {
    width: 100%;
    background: #2d2d2d;
    color: #fff;
    border-radius: 5px;
    padding: 15px;
    font-family: monospace;
    font-size: 14px;
}

/* Online Judge */
.online-judge {
    margin-top: 20px;
}

.judge-results {
    margin-top: 10px;
    padding: 10px;
    background: #e7f4e4;
    border: 1px solid #94c47c;
    border-radius: 5px;
    color: #4CAF50;
}

/.judge-error {
    background: #f8d7da;
    color: #a94442;
}

/* User Profiles */
.user-profile {
    display: flex;
    align-items: center;
    margin-top: 20px;
    padding: 15px;
    border: 1px solid #ddd;
    border-radius: 5px;
    background: white;
}

.user-profile img {
    border-radius: 50%;
    margin-right: 15px;
}

.user-profile h2 {
    margin: 0;
}

/* Leaderboard */
.leaderboard {
    margin-top: 40px;
}

.leaderboard table {
    width: 100%;
    border-collapse: collapse;
}

.leaderboard th, .leaderboard td {
    text-align: left;
    padding: 10px;
    border-bottom: 1px solid #ddd;
}

.leaderboard th {
    background: #4CAF50;
    color: white;
}

.leaderboard tr:hover {
    background-color: #f1f1f1;
}

/* Hints and Tutorials */
.hints-tutorials {
    margin-top: 40px;
    padding: 20px;
    background: #fff3cd;
    border: 1px solid #ffeeba;
    border-radius: 5px;
    color: #856404;
}

.hints-tutorials h4 {
    margin-top: 0;
}

/* Responsive Design */
@media (max-width: 768px) {
    .container {
        width: 100%;
        padding: 10px;
    }

    .problem-library {
        grid-template-columns: 1fr;
    }
}

